window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"UeE9RZK7K2o","speaker":"Sugiono","role":"Foreign Minister","country":"Indonesia","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=UeE9RZK7K2o","date":"20260926","title":"🇮🇩 Indonesia - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1072,"words":1826,"counts":{"claims":25,"promises":5,"attacks":0},"topics":[{"topic":"UN reform","share":0.3868,"seconds":415},{"topic":"Palestine","share":0.1289,"seconds":138},{"topic":"Indonesia resilience","share":0.1259,"seconds":135},{"topic":"ASEAN","share":0.1193,"seconds":128},{"topic":"Ceremony","share":0.0641,"seconds":69},{"topic":"Indonesia diversity","share":0.0594,"seconds":64},{"topic":"Indonesia economy","share":0.0592,"seconds":63},{"topic":"Indonesia foreign policy","share":0.0566,"seconds":61}],"timeline":[[4,68,"Ceremony"],[75,148,"UN reform"],[149,224,"Indonesia resilience"],[225,288,"Indonesia economy"],[291,354,"Indonesia diversity"],[356,417,"Indonesia resilience"],[419,485,"ASEAN"],[486,548,"ASEAN"],[550,640,"UN reform"],[643,705,"Palestine"],[706,782,"Palestine"],[784,847,"UN reform"],[849,913,"UN reform"],[915,980,"UN reform"],[981,1041,"Indonesia foreign policy"],[1042,1102,"UN reform"],[1120,1125,"Ceremony"]],"stances":{"Ceremony":"Sugiono delivers formal greetings to the assembly and acknowledges key UN officials.","UN reform":"Sugiono states that Indonesia and the UN share a founding promise to build a future of peace following World War II.","Indonesia resilience":"Sugiono states that Indonesia developed the concept of national resilience in the 1960s to safeguard identity, protect sovereignty and unity, and sustain development.","Indonesia economy":"Sugiono states that Indonesia is building an economy focused on self-sufficiency, energy security, and resilience to withstand shocks.","Indonesia diversity":"Sugiono states that Indonesia manages its diversity through democratic dialogue and respect to preserve national unity.","ASEAN":"Sugiono states that national resilience supports a stable and peaceful region, highlighting ASEAN's demographic and economic strengths while emphasizing the organization's commitment to maintaining dialogue despite differences.","Palestine":"Sugiono asserts that the situation in Palestine and Gaza represents a clear violation of international law and a test of global conscience, drawing parallels to the pre-UN era and noting Indonesia's historical experience with colonialism.","Indonesia foreign policy":"Sugiono states that Indonesia will maintain open dialogue, uphold the UN Charter, and engage with all partners to foster cooperation."},"claims":[{"t":86,"quote":"81 years ago from the ashes of the second world war Indonesia and the United Nations were We emerge from a world devastated by war with a shared conviction that never again should humanity leave its future to war and division.","topic":"UN reform","kind":"fact"},{"t":123,"quote":"For eight decades, we have worked to turn that promise into progress.","topic":"UN reform","kind":"number"},{"t":209,"quote":"In the 1960s, Indonesia developed the concept of national resilience to safeguard our identity, to protect our sovereignty and unity, and to sustain our development in the face of challenges and obstacles.","topic":"Indonesia resilience","kind":"fact"},{"t":251,"quote":"For Indonesia, this means building greater self-sufficiency in food and strengthening our energy security.","topic":"Indonesia economy","kind":"fact"},{"t":300,"quote":"As a nation of more than 280 million people, Indonesia has learned that diversity is not something to overcome.","topic":"Indonesia diversity","kind":"number"},{"t":324,"quote":"From Ache to Papua, from Miangas to Rot, Indonesia is one people. Indonesia is one nation.","topic":"Indonesia diversity","kind":"fact"},{"t":387,"quote":"A food secure Indonesia can contribute more to regional and global food The more energy resilient Indonesia can contribute more to the global energy a stronger economy opens greater opportunities for cooperation and shared prosperity.","topic":"Indonesia resilience","kind":"fact"},{"t":434,"quote":"Southeast Asia is home to one of the world's largest productive age populations. It is now the world's fifth largest economy, supported by a large and fast growing digital economy.","topic":"ASEAN","kind":"fact"},{"t":476,"quote":"For almost six decades, Azan has managed differences, maintained communication, and continued seeking common ground.","topic":"ASEAN","kind":"fact"},{"t":486,"quote":"This is the strength that comes from Azan unity and centrality. It enables us to engage all partners and preserve space for dialogue and even as a strategic competition intensifies around us.","topic":"ASEAN","kind":"fact"},{"t":537,"quote":"The United Nations give nations the space to resolve differences without resorting to conflict. It provides common rules when interests compete.","topic":"ASEAN","kind":"fact"},{"t":550,"quote":"And it allows us to combine our capacities when no country can act effectively alone.","topic":"UN reform","kind":"fact"},{"t":570,"quote":"Let us be clear that the answer to imperfect multilateralism is not less multilateralism.","topic":"UN reform","kind":"fact"},{"t":670,"quote":"The clear violation of international law in Gaza and the West Bank are reminiscent of our world pre945, a world pre the UN charter, pre the universal declaration of human rights and pre the four 1949 Geneva A World where a certain race was almost","topic":"Palestine","kind":"fact"},{"t":696,"quote":"Indonesia knows what it means to struggle against colonialism. to struggle in a world where international law was weak and might was right.","topic":"Palestine","kind":"self_credit"},{"t":706,"quote":"Our nation's journey to independence has shaped our consistent support for the Palestinian people and their right to determine their own future.","topic":"Palestine","kind":"fact"},{"t":718,"quote":"Indonesia will continue to stand with the Palestinian people until their right to self-determination is fulfilled and until an independent and sovereign state of Palestine is realized based on the two-state solution in accordance with international law and internationally agreed parameters.","topic":"Palestine","kind":"fact"},{"t":795,"quote":"Secretary General Antonio Gutirez has led this organization through an exceptionally challenging period, wars and geopolitical tensions, a global pandemic, humanitarian emergencies and rapid technological transformation.","topic":"UN reform","kind":"fact"},{"t":882,"quote":"We have been among the top tier contributors to UN peacekeeping missions, deploying personnel to missions around the world since 1957.","topic":"UN reform","kind":"fact"},{"t":895,"quote":"For nearly two decades, Indonesian peacekeepers have served under under the UN flag in Lebanon.","topic":"UN reform","kind":"fact"},{"t":945,"quote":"Indonesia present its candidature for a non-permanent seat on the UN Security Council for the 2029 2030 term.","topic":"UN reform","kind":"fact"},{"t":1006,"quote":"As President Prabosanto mentioned in his very lecture last year, 1,000 friends are too few and an enemy is too many.","topic":"Indonesia foreign policy","kind":"fact"},{"t":1035,"quote":"81 years ago, Indonesia fought against colonialism so we could chart our own future.","topic":"Indonesia foreign policy","kind":"fact"},{"t":1050,"quote":"one year ago President Prabos Subanto called upon us to draw closer not drift apart","topic":"UN reform","kind":"fact"},{"t":1095,"quote":"fulfill the promise we made 81 years ago","topic":"UN reform","kind":"number"}],"promises":[{"t":929,"quote":"We will carry our diplomacy forward through humanitarian assistance, through peace building, and through engagement across regions and institutions.","topic":"UN reform","kind":"promise"},{"t":957,"quote":"Our commitment is clear. Fostering advancing peace. Fostering unity means rebuilding trust in the multilateral system and keeping channels of dialogue open.","topic":"UN reform","kind":"promise"},{"t":990,"quote":"We will uphold the UN charter consistently to maintain international peace and security.","topic":"Indonesia foreign policy","kind":"promise"},{"t":997,"quote":"We will bring the same principle that guides our foreign policy to engage with all and keep the space for cooperation open.","topic":"Indonesia foreign policy","kind":"promise"},{"t":1042,"quote":"Today we reaffirm our promise for a future peace we all share","topic":"UN reform","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":4,"topic":"Ceremony","text":"I now invite his excellency so the minister foreign affairs of Indonesia to address the assembly Your Excellency Hal Rahman, President of the 81st session of the United Nations General Assembly. Your Excellency Antonio Gutirez, Secretary General of the United Nations, Heads of State, and Heads of Government, Ministers, distinguished delegates, ladies and gentlemen. Assalamu alaykumati. Shalom salomastay."},{"t":75,"topic":"UN reform","text":"May peace be upon all of us. 81 years ago from the ashes of the second world war Indonesia and the United Nations were We emerge from a world devastated by war with a shared conviction that never again should humanity leave its future to war and division. And we shared a founding promise to build a future of peace. For eight decades, we have worked to turn that promise into progress. Nations freed themselves from Globalization connected our economy. Technology transformed our societies and development improves the lives of But progress has never been linear."},{"t":149,"topic":"Indonesia resilience","text":"We have lived through financial crisis, a global pandemic, climate disasters, geopolitical rivalries and conflicts around the world. With every transformation and every crisis, one lesson remains clear. For peace and prosperity to endure, must be resilient. It must be able to adapt, to respond, and most importantly to deliver. Because multilateralism that cannot deliver, we lose people's trust. And without trust, multilateralism will never endure. Building resilient multilateralism begins at hope. Begins with resilient nations. It starts at home. And Indonesia has long understood this for In the 1960s, Indonesia developed the concept of national resilience to safeguard our identity, to protect our sovereignty and unity, and to sustain our development in the face of challenges and obstacles."},{"t":225,"topic":"Indonesia economy","text":"At the heart of our resilience are our people. A nation that is resilient when families A nation is resilient when families can provide for their households. When farmers can produce. When workers can find decent jobs. And when children can learn, grow, and dream about their For Indonesia, this means building greater self-sufficiency in food and strengthening our energy security. Most importantly, this also means investing in the future of our people, ensuring our children receive quality education and ensuring our people have access to essential healthcare. At the same time, we are building an economy that can withstand shocks and create opportunities, more jobs, stronger industries, and greater productive capacity."},{"t":291,"topic":"Indonesia diversity","text":"Central to our resilience is our ability to manage differences and preserve our As a nation of more than 280 million people, Indonesia has learned that diversity is not something to overcome. It is something to manage, respect and turn into strength. Through democratic dialogue and respect for differences. We we preserve our unity. From Ache to Papua, from Miangas to Rot, Indonesia is one people. Indonesia is one nation. We also continue to strengthen the promotion and protection of human rights through our national mechanisms and our commitment to international human rights This goes hand inhand with building our national resilience because human rights are not only the absence of violence."},{"t":356,"topic":"Indonesia resilience","text":"They are also about ensuring that people have food, education and healthcare. To our neighbors, friends, and partners, let there be no doubt Indonesia stands strong today, grounded firmly in democracy, human rights, and the rule of law. And when nations are resilient at home, they have greater capacity to contribute beyond their borders. A food secure Indonesia can contribute more to regional and global food The more energy resilient Indonesia can contribute more to the global energy a stronger economy opens greater opportunities for cooperation and shared prosperity. This is how national resilience becomes collective resilience and this is how resilience helps us advance the SDGs."},{"t":419,"topic":"ASEAN","text":"Mr. President, a resilient nation contributes to a resil resilient region. Our national resilience will support and complement a region that is stable, peaceful, and Southeast Asia is home to one of the world's largest productive age populations. It is now the world's fifth largest economy, supported by a large and fast growing digital economy. At the center of this dynamic region is Azan brings together nations with different histories, political systems, level of development and national interest. We do not always agree, but we have made a conscious choice to stay together and we choose to keep talking even when agreement is difficult. For almost six decades, Azan has managed differences, maintained communication, and continued seeking common ground."},{"t":486,"topic":"ASEAN","text":"This is the strength that comes from Azan unity and centrality. It enables us to engage all partners and preserve space for dialogue and even as a strategic competition intensifies around us. At the same time, building a resilient region requires the ability to adapt. This is why Azan must continue to evolve so that it remains fit for purpose and beneficial for its people and the wider region. resilience at home and at the regional level must be matched by a multilateral system capable of supporting and sustaining it. This is where the United Nations remain The United Nations give nations the space to resolve differences without resorting to conflict. It provides common rules when interests compete."},{"t":550,"topic":"UN reform","text":"And it allows us to combine our capacities when no country can act effectively alone. This is why Indonesia continues to believe in the United But believing in the United Nations also means believing that it must evolve with the world it serves. Let us be clear that the answer to imperfect multilateralism is not less multilateralism. It is a stronger and better multilateralism. A multilateral system fit for the 21st century must be more representative, more agile, and better able to deliver. Institutional transformation will not happen overnight, but the urgency of today's challenges requires us to act We must start by strengthening our collective capacity to withstand crisis, responding effectively to global crisis and humanitarian situations and sustaining peace development and At the same time, international financial architecture must also evolve to respond better to the needs of developing countries and to give them greater space to pursue their own development priorities and build their But stronger institutions alone will not save multilateralism."},{"t":643,"topic":"Palestine","text":"institution are only as strong as the principles we are willing to uphold. International law must be upheld Sovereignty must be respected and colonialism must be brought to an end. This is where Palestine remains one of the clearest test of these principles and the test of our conscience. The clear violation of international law in Gaza and the West Bank are reminiscent of our world pre945, a world pre the UN charter, pre the universal declaration of human rights and pre the four 1949 Geneva A world where a certain race was almost Indonesia knows what it means to struggle against colonialism. to struggle in a world where international law was weak and might was right."},{"t":706,"topic":"Palestine","text":"Our nation's journey to independence has shaped our consistent support for the Palestinian people and their right to determine their own future. Indonesia will continue to stand with the Palestinian people until their right to self-determination is fulfilled and until an independent and sovereign state of Palestine is realized based on the two-state solution in accordance with international law and internationally agreed parameters. Palestine is not only a question for one region. It is a test of whether multilateral system can uphold the very principles it was created to defend and whether it can deliver when it matters Mr. President, an effective multilateral system also requires effective leadership. Indonesia's leadership philosophy passed down through generations teaches us that leaders must possess the capability to lead by example from the front, build confidence while standing among the people and empower from behind."},{"t":784,"topic":"UN reform","text":"Leadership is not simply about It is about exercising wisdom and giving others the strength to move forward. Secretary General Antonio Gutirez has led this organization through an exceptionally challenging period, wars and geopolitical tensions, a global pandemic, humanitarian emergencies and rapid technological transformation. Indonesia expresses its appreciation for his leadership and service over the past Throughout these challenges, the UN continues to provide an important platform for dialogue and collective problem solving. The next secretary general will carry an equally important responsibility to uphold the charter, strengthen the organization, and to translate multilateralism into concrete results for people."},{"t":849,"topic":"UN reform","text":"Effective leadership must also be accompanied with the full commitment of member states to make multilateralism Indonesia is prepared to carry its share as our constitution mandates us to contribute to a world based on freedom, lasting peace and social justice. Through diplomacy and mediation, Indonesia has contributed to resolving conflicts in the region and beyond. We have been among the top tier contributors to UN peacekeeping missions, deploying personnel to missions around the world since 1957. For nearly two decades, Indonesian peacekeepers have served under under the UN flag in Lebanon. UNIFIL may be entering its final chapter, but Indonesia's commitment does not end with the mission."},{"t":915,"topic":"UN reform","text":"The experience, sacrifice, and dedication of our peacekeepers will continue to shape Indonesia's contribution to international peace and security. We will carry our diplomacy forward through humanitarian assistance, through peace building, and through engagement across regions and institutions. Mr. President, it is in this spirit that Indonesia present its candidature for a non-permanent seat on the UN Security Council for the 2029 2030 term. Our commitment is clear. Fostering advancing peace. Fostering unity means rebuilding trust in the multilateral system and keeping channels of dialogue open. Advancing peace requires us to uphold international law and make effective use of the tools available to us."},{"t":981,"topic":"Indonesia foreign policy","text":"Indonesia will work to keep dialogue open, build common ground, and turn shared responsibility into practical We will uphold the UN charter consistently to maintain international peace and security. We will bring the same principle that guides our foreign policy to engage with all and keep the space for cooperation open. As President Prabosanto mentioned in his very lecture last year, 1,000 friends are too few and an enemy is too many. The same approach guides Indonesia's engagement with all partners through Azan G20 D8 bricks MKTA and the UN Indonesia will extend the friendship to deliver practical Mr. President, 81 years ago, Indonesia fought against colonialism so we could chart our own future."},{"t":1042,"topic":"UN reform","text":"Today we reaffirm our promise for a future peace we all share. Also one year ago President Prabos Subanto called upon us to draw closer not drift apart. Today I carry that call forward. And as we draw closer closer let us also make each other stronger. Strong enough for our nations to withstand crisis. strong enough for our regions to preserve cooperation. Strong enough for our institutions to deliver for people. Because resilience is not simply about surviving the storms. It is about having the strength to keep moving forward together. And only through our collective collective resilience can the United Nations be strong enough to fulfill the promise we made 81 years ago. A future of peace for generations to come. I thank you."},{"t":1120,"topic":"Ceremony","text":"I thank the Minister for F for Foreign Affairs of Indonesia."}],"compare":[{"topic":"UN & its reform","share":0.4133,"mean":0.2037,"rank":17,"others":170},{"topic":"Israel–Palestine","share":0.1377,"mean":0.052,"rank":17,"others":76},{"topic":"ASEAN","share":0.1275,"mean":0.0014,"rank":1,"others":4}]};
